CREATE TABLE case_map_areas (id VARCHAR(36) PRIMARY KEY, case_id VARCHAR(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, area_type VARCHAR(20) NOT NULL CHECK (area_type IN ('search','searched','risk','rally')), status VARCHAR(20) NOT NULL CHECK (status IN ('candidate','pending_review','approved','rejected')), title VARCHAR(200) NOT NULL, description TEXT NULL, task_id VARCHAR(36) NULL REFERENCES tasks(id) ON DELETE SET NULL, clue_id VARCHAR(36) NULL REFERENCES clues(id) ON DELETE SET NULL, version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), created_by_user_id VARCHAR(36) NOT NULL REFERENCES users(id), reviewed_by_user_id VARCHAR(36) NULL REFERENCES users(id), reviewed_at VARCHAR(40) NULL, starts_at VARCHAR(40) NULL, ends_at VARCHAR(40) NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
-- statement-break
CREATE INDEX idx_case_map_areas_case_status ON case_map_areas(case_id, status, updated_at);
-- statement-break
CREATE TABLE case_map_area_vertices (area_id VARCHAR(36) NOT NULL REFERENCES case_map_areas(id) ON DELETE CASCADE, vertex_order INTEGER NOT NULL CHECK (vertex_order >= 0), latitude DOUBLE PRECISION NOT NULL CHECK (latitude BETWEEN -90 AND 90), longitude DOUBLE PRECISION NOT NULL CHECK (longitude BETWEEN -180 AND 180), PRIMARY KEY(area_id, vertex_order));
